// Claudashboard: session vitals, running subagents, and a file explorer with an in-pane preview.
// This module wires the engine's events to the modules that do the work.
import type { EngineInterface, Register } from 'claude-code'
import type { Agent, Entry } from '../types'
import { contextLevel, pushTurn, usageToVitals } from './session/vitals'
import { describeTool, finishAgent, keepAgents, normalizeAgent, stepAgent } from './agents/agents'
import { agentLines, reduceAgentsKey } from './agents/view'
import { helpLines, reduceHelp } from './help'
import { findFiles, reduceFinder } from './explorer/finder'
import { editMessage, enterEdit, leaveEdit, saveFile } from './explorer/editor/editing'
import type { UiMessage } from './explorer/client'
import { DEFAULT_EXPLORER, reduceKey, selectLine, visibleEntries } from './explorer/model'
import { loadDir, loadPreview, noteEdit, openDiff, openFinder, openFound, poll } from './explorer/files'
import { refreshGit } from './explorer/git/git'
import { ONE_DARK, THEME, registerPane } from './pane'
import { isAbsolute, parentOf, relTo, toSlash } from './shared/paths'
import {
  PANE,
  getAgents,
  getExplorer,
  getView,
  getVitals,
  logged,
  updateActivity,
  openPane,
  paneState,
  setExplorer,
  setPreview,
  toKey,
  updateAgents,
  updateExplorer,
  updateTouched,
  updateView,
  updateVitals,
} from './state'

const EDIT_TOOLS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit'])

async function goUp($: EngineInterface) {
  const ex = await getExplorer($)
  if (ex.preview?.mode === 'edit') return leaveEdit($)
  if (ex.preview) {
    await updateExplorer($, x => ({ ...x, preview: null }))
    void refreshGit($).catch(logged($, 'refreshGit'))
    return
  }
  if (ex.onlyTouched) {
    await updateExplorer($, x => ({ ...x, onlyTouched: false }))
    return loadDir($, ex.dir)
  }
  if (!ex.dir) return
  return loadDir($, parentOf(ex.dir), ex.dir)
}

async function openEntry($: EngineInterface, entry: Entry, edit = false) {
  if (entry.kind === 'dir') return loadDir($, entry.path)
  await loadPreview($, entry.path)
  if (edit) await enterEdit($)
}

async function mention($: EngineInterface, path: string) {
  const filled = await $.prompt.fill({ text: `@${path} `, mode: 'insert' })
  $.ui.toast(filled.isFilled ? `@${path} added to your prompt` : 'The prompt is busy; try again when it is free')
}

async function initExplorer($: EngineInterface, showHidden: boolean) {
  const root = toSlash(await $.session.cwd())
  const ex = await getExplorer($)
  // Keep where the person was across reloads; start over when the session moved to another folder.
  if (ex.root === root) {
    await updateExplorer($, x => ({ ...x, showHidden }))
    return loadDir($, ex.dir)
  }
  await setExplorer($, { ...DEFAULT_EXPLORER, root, showHidden })
  return loadDir($, '')
}

/** The context level last announced: each threshold toasts once on the way up, and a compaction resets it. */
let announced: 0 | 1 | 2 = 0

/** A toast as the context crosses 80% and 90%, and a status line under the prompt while it stays there. */
function alarmContext($: EngineInterface, pct: number | null) {
  const level = contextLevel(pct)
  const n = Math.round(pct ?? 0)
  if (level > announced) $.ui.toast(level === 2 ? `Context ${n}% full: run /compact soon` : `Context ${n}% full`)
  if (level > 0) $.ui.status(level === 2 ? `⚠ context ${n}%: compact soon` : `⚠ context ${n}%`)
  else if (announced > 0) $.ui.status(undefined)
  announced = level
}

async function refreshUsage($: EngineInterface) {
  const u = await $.session.usage().catch(() => null)
  if (!u) return
  await updateVitals($, x => ({ ...x, ...usageToVitals(u) }))
  alarmContext($, u.context?.percent ?? null)
}

/** The main loop's permission mode, from a classic hook's input; a subagent's events are left out. */
async function noteMode($: EngineInterface, e: { permission_mode?: string; agent_id?: string }) {
  const mode = e.permission_mode
  if (!mode || e.agent_id) return
  await updateVitals($, x => (x.mode === mode ? x : { ...x, mode })).catch(logged($, 'permission mode'))
}

/** Marks the file a Read or an edit tool is about to touch; an edit outranks a read for the rest of the turn. */
async function noteActivity($: EngineInterface, e: { tool: string }) {
  const kind = e.tool === 'Read' ? 'read' : EDIT_TOOLS.has(e.tool) ? 'edit' : null
  if (!kind) return
  const input = e as unknown as { file_path?: unknown; notebook_path?: unknown }
  const given = typeof input.file_path === 'string' ? input.file_path : typeof input.notebook_path === 'string' ? input.notebook_path : null
  if (!given) return
  const path = relTo((await getExplorer($)).root, toSlash(given))
  await updateActivity($, a => (a[path] === 'edit' || a[path] === kind ? a : { ...a, [path]: kind }))
}

async function refreshModel($: EngineInterface) {
  const model = await $.session.model().catch(() => '')
  if (model) await updateVitals($, x => ({ ...x, model }))
}

/** Adds a card for a spawned subagent. */
async function noteSpawn(
  $: EngineInterface,
  e: { name?: string; subagentType?: string; description?: string; background?: boolean },
  id: string,
  model: string | undefined,
) {
  const type = e.subagentType ?? 'agent'
  const agent: Agent = normalizeAgent({
    id,
    name: e.name ?? type.split(':').pop() ?? 'agent',
    type,
    model: model ?? '',
    task: e.description ?? '',
    startedAt: await $.clock.now(),
    isBackground: e.background === true,
  })
  await updateAgents($, list => keepAgents([...list.filter(a => a.id !== agent.id), agent]))
}

const COMMANDS = ['claudashboard', 'cdb'] as const

export const register: Register = (on, options) => {
  const C = options.palette === 'theme' ? THEME : ONE_DARK
  const showHiddenDefault = options.showHidden === true

  on('session.start', async ($, e, next) => {
    // /cdb is the short form of /claudashboard.
    for (const name of COMMANDS) {
      await $.command.register({
        name,
        description: 'Claudashboard: open or close the hub, show a tab, jump the explorer to a folder, show the turns row, or reset it',
        argumentHint: '[close|files|agents|cd <path>|save|reset|turns [on|off]]',
      })
    }
    await Promise.all([refreshUsage($), refreshModel($)]).catch(logged($, 'session vitals'))
    // The turns row is off unless the person turned it on, in this session or an earlier one.
    const showTurns = (await $.store.get('showTurns').catch(() => undefined)) === true
    await updateVitals($, v => ({ ...v, showTurns })).catch(logged($, 'showTurns'))
    await initExplorer($, showHiddenDefault).catch(logged($, 'initExplorer'))
    if (options.openOnStart !== false) void openPane($).catch(logged($, 'openPane'))
    // Live refresh: edits made in another editor, git add/commit run elsewhere.
    $.clock.every(3000, () => poll($).catch(logged($, 'poll')))
    return next(e)
  })

  // The person closed the pane (its ✕) or the module unloads: stop asking git and the disk.
  on('ui.close', { id: PANE }, async ($, e, next) => {
    paneState.isOpen = false
    return next(e)
  })

  on('session.end', async ($, e, next) => {
    if (e.reason === 'clear') {
      await updateAgents($, () => [])
      await updateActivity($, () => ({}))
    }
    return next(e)
  })

  for (const command of COMMANDS)
    on('command.run', { command }, async ($, e) => {
      const args = e.args.trim()
      const [verb = ''] = args.split(/\s+/)
      if (verb === 'close') {
        await $.ui.close({ id: PANE })
        paneState.isOpen = false
        return { text: 'Claudashboard closed.' }
      }
      if (verb === 'turns') {
        // `turns` flips the row; `turns on` / `turns off` set it.
        const arg = args.split(/\s+/)[1] ?? ''
        const before = (await getVitals($)).showTurns
        const showTurns = arg === 'on' ? true : arg === 'off' ? false : !before
        await updateVitals($, v => ({ ...v, showTurns }))
        await $.store.set('showTurns', showTurns).catch(logged($, 'showTurns'))
        return { text: showTurns ? 'Claudashboard: turns row on (cost and length of the last turns).' : 'Claudashboard: turns row off.' }
      }
      if (verb === 'files' || verb === 'agents') {
        await updateView($, v => ({ ...v, tab: verb, help: false }))
        await openPane($)
        return { text: `Claudashboard: ${verb} tab.` }
      }
      if (verb === 'reset') {
        await updateTouched($, () => ({}))
        await updateActivity($, () => ({}))
        await updateAgents($, () => [])
        await setExplorer($, DEFAULT_EXPLORER)
        await initExplorer($, showHiddenDefault)
        return { text: 'Claudashboard reset: explorer back at the root, touched files and agents cleared.' }
      }
      if (verb === 'save') {
        const p = (await getExplorer($)).preview
        if (!p || p.mode !== 'edit') return { text: 'Nothing to save: open a file and press e to edit it.' }
        await saveFile($)
        const after = (await getExplorer($)).preview
        return { text: `Claudashboard: ${after?.status ?? 'saved'}` }
      }
      if (verb === 'cd') {
        const ex = await getExplorer($)
        const target = toSlash(args.slice(2).trim())
          .replace(/^\.\/?/, '')
          .replace(/\/+$/, '')
        const root = ex.root.replace(/\/+$/, '')
        const rel = target === root ? '' : isAbsolute(target) ? relTo(root, target) : target
        if (isAbsolute(rel) || rel.split('/').includes('..')) return { text: `${target} is outside ${ex.root}.` }
        await updateExplorer($, x => ({ ...x, onlyTouched: false, filter: '' }))
        await loadDir($, rel)
        const after = await getExplorer($)
        if (after.error) return { text: `Claudashboard: ${after.error}` }
        await openPane($)
        return { text: `Claudashboard explorer at ./${rel}` }
      }
      await refreshModel($)
      const opened = await openPane($)
      if (!opened.isPlaced) return { text: `Claudashboard is not shown yet: ${opened.reason ?? 'no room'}` }
      return { text: 'Claudashboard open. Click the file list to give it the keyboard; Esc hands it back.' }
    })

  // The engine raises nothing when the person switches mode (Shift+Tab), but every classic hook carries
  // the mode: a prompt, each tool call, the end of a turn, and Claude waiting for the person.
  on('classic.UserPromptSubmit', async ($, e, next) => {
    await noteMode($, e)
    return next(e)
  })
  on('classic.PostToolUse', async ($, e, next) => {
    await noteMode($, e)
    return next(e)
  })
  on('classic.Stop', async ($, e, next) => {
    await noteMode($, e)
    return next(e)
  })
  on('classic.Notification', async ($, e, next) => {
    await noteMode($, e)
    return next(e)
  })

  // turn.start is the main loop's alone: a subagent's turn never raises it.
  on('turn.start', async ($, e, next) => {
    const [now, u] = await Promise.all([$.clock.now(), $.session.usage().catch(() => null)])
    await updateVitals($, x => ({ ...x, turnStartedAt: now, turnCostStart: u?.cost?.usd ?? null }))
    return next(e)
  })

  on('turn.step', async function* ($, e, next) {
    if (!e.agentId) {
      await updateVitals($, v => ({ ...v, model: e.model, effort: e.effort === undefined ? v.effort : String(e.effort) }))
      return yield* next(e)
    }
    const result = yield* next(e)
    const id = e.agentId
    await updateAgents($, list => list.map(a => (a.id === id ? stepAgent(a, e.model, result.usage) : a))).catch(logged($, 'agent step'))
    return result
  })

  on('agent.spawn', async ($, e, next) => {
    const started = await next(e)
    if (started.deny !== undefined || !started.agentId) return started
    // Bookkeeping only: a failure here must never fail the Agent call.
    await noteSpawn($, e, started.agentId, started.model).catch(logged($, 'agent spawn'))
    return started
  })

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    if (e.agentId) {
      // A finished agent moves to the history.
      const id = e.agentId
      const now = await $.clock.now()
      await updateAgents($, list => finishAgent(list, id, now)).catch(logged($, 'agent done'))
      return done
    }
    void refreshGit($).catch(logged($, 'refreshGit'))
    await updateActivity($, () => ({})).catch(logged($, 'activity'))
    const [now, u] = await Promise.all([$.clock.now(), $.session.usage().catch(() => null)])
    await updateVitals($, v => {
      const cost = u?.cost?.usd ?? null
      const turnCost = cost !== null && v.turnCostStart !== null ? cost - v.turnCostStart : null
      return {
        ...v,
        turnStartedAt: null,
        lastTurnMs: v.turnStartedAt === null ? v.lastTurnMs : now - v.turnStartedAt,
        lastTurnCost: turnCost ?? v.lastTurnCost,
        costUsd: cost ?? v.costUsd,
        turns: v.turnStartedAt === null ? v.turns : pushTurn(v.turns, { ms: now - v.turnStartedAt, cost: turnCost }),
      }
    })
    return done
  })

  on('session.measure', async ($, e, next) => {
    await updateVitals($, x => ({ ...x, ...usageToVitals(e) }))
    alarmContext($, e.context?.percent ?? null)
    return next(e)
  })

  on('session.compact', async ($, e, next) => {
    const done = await next(e)
    if (!e.agentId && e.trigger !== 'precompute') {
      await updateVitals($, v => ({ ...v, compactions: v.compactions + 1 })).catch(logged($, 'compaction'))
    }
    return done
  })

  on('tool.call', async ($, e, next) => {
    // An agent's current activity shows as the call starts, not once it ends.
    if (e.agentId) {
      const id = e.agentId
      const what = describeTool(e.tool, e as unknown as Record<string, unknown>)
      await updateAgents($, list => list.map(a => (a.id === id ? { ...a, tools: a.tools + 1, lastTool: what } : a))).catch(logged($, 'agent tool'))
    }
    // The file tree colours a file while Claude reads or edits it: set as the call starts.
    await noteActivity($, e).catch(logged($, 'activity'))
    const ran = await next(e)
    if (!EDIT_TOOLS.has(e.tool) || ran.deny !== undefined || ran.isError === true) return ran
    // Bookkeeping only: a failure here must never change the call's result.
    await noteEdit($, e).catch(logged($, 'noteEdit'))
    return ran
  })

  on('ui.message', async ($, e) => {
    // The explorer client sends these; the checks below still guard each field.
    const d = e.data as UiMessage
    const room = Math.max(3, Number(d.room) || 10)
    const ex = await getExplorer($)
    const view = await getView($)
    const k = d.k === 'key' && typeof d.key === 'string' ? toKey(d) : null
    if (d.k === 'tab') {
      await updateView($, v => ({ ...v, tab: d.tab === 'agents' ? 'agents' : 'files', help: false }))
      return {}
    }
    // The help sits over either tab: arrows scroll it, any other key or a click on its title closes it.
    if (view.help) {
      if (k) await updateView($, v => reduceHelp(v, k, helpLines('list').length, room))
      else if (d.k === 'crumb') await updateView($, v => ({ ...v, help: false, helpTop: 0 }))
      return {}
    }
    // Tab switches tabs, except where it types: editing, or finishing a filter.
    const isTyping = ex.preview?.mode === 'edit' || ex.isFiltering
    if (k?.key === 'tab' && !k.ctrl && (view.tab === 'agents' || !isTyping)) {
      await updateView($, v => ({ ...v, tab: v.tab === 'agents' ? 'files' : 'agents' }))
      return {}
    }
    if (k?.key === '?' && (view.tab === 'agents' || (!isTyping && !ex.finder))) {
      await updateView($, v => ({ ...v, help: true, helpTop: 0 }))
      return {}
    }
    if (view.tab === 'agents') {
      if (!k) return {}
      const agents = await getAgents($)
      const r = reduceAgentsKey(view, k, agentLines(agents).length, room)
      if (r.view !== view) await updateView($, () => r.view)
      if (r.effect?.kind === 'clear') await updateAgents($, list => list.filter(a => a.endedAt === null))
      return {}
    }
    if (ex.finder) {
      const f = ex.finder
      if (d.k === 'crumb') await updateExplorer($, x => ({ ...x, finder: null }))
      if (d.k === 'pick' && typeof d.index === 'number') {
        const picked = findFiles(f.files, f.query)[d.index]
        if (picked) await openFound($, picked.path)
      }
      if (!k) return {}
      const r = reduceFinder(f, k, room)
      if (r.finder !== f) await updateExplorer($, x => ({ ...x, finder: r.finder }))
      if (r.effect?.kind === 'open') await openFound($, r.effect.path)
      else if (r.effect?.kind === 'close') await updateExplorer($, x => ({ ...x, finder: null }))
      return {}
    }
    if (ex.preview?.mode === 'edit') {
      await editMessage($, ex.preview, d, room)
      return {}
    }
    if (d.k === 'mode') {
      if (ex.preview) await enterEdit($)
      return {}
    }
    if (d.k === 'line' && typeof d.row === 'number' && ex.preview && !ex.preview.diff) {
      const line = ex.preview.top + d.row
      await setPreview($, p => selectLine(p, line, d.isExtend === true))
      return {}
    }
    if (d.k === 'click' && typeof d.index === 'number') {
      const entry = visibleEntries(ex)[d.index]
      if (entry) {
        await updateExplorer($, x => ({ ...x, cursor: d.index }))
        await openEntry($, entry)
      }
      return {}
    }
    if (d.k === 'crumb') {
      if (ex.isFiltering || ex.filter) await updateExplorer($, x => ({ ...x, isFiltering: false, filter: '', cursor: 0 }))
      await goUp($)
      return {}
    }
    if (d.k !== 'key' || typeof d.key !== 'string') return {}
    const { ex: nextEx, effect } = reduceKey(ex, toKey(d), room, Math.max(20, Number(d.width) || 80))
    if (nextEx !== ex) await setExplorer($, nextEx)
    if (effect?.kind === 'open') await openEntry($, effect.entry, effect.edit === true)
    else if (effect?.kind === 'edit') await enterEdit($)
    else if (effect?.kind === 'up') await goUp($)
    else if (effect?.kind === 'mention') await mention($, effect.path)
    else if (effect?.kind === 'diff') await openDiff($)
    // The listing can take a while in a large tree: the finder opens at once and fills in when it is done.
    else if (effect?.kind === 'find') void openFinder($).catch(logged($, 'finder'))
    else if (effect?.kind === 'reload') await (nextEx.preview ? refreshGit($) : loadDir($, nextEx.dir))
    return {}
  })

  registerPane(on, C)
}

files.hooks/session/vitals.ts:
// Pure logic for Claudashboard: the session's vitals. No `$` here, so it is testable.
import type { Turn, Vitals } from '../../types'

export const DEFAULT_VITALS: Vitals = {
  model: '',
  effort: '',
  mode: 'default',
  pct: null,
  tokens: null,
  window: null,
  costUsd: null,
  limits: [],
  compactions: 0,
  turnStartedAt: null,
  turnCostStart: null,
  lastTurnMs: null,
  lastTurnCost: null,
  turns: [],
  showTurns: false,
}

export type Usage = {
  context?: { percent?: number | null; tokens?: number | null; window?: number | null } | null
  cost?: { usd?: number | null } | null
  rateLimits?: Array<{ kind: string; percentUsed: number }> | null
}
/** The vitals a usage report (from `session.usage()` or `session.measure`) sets. */
export const usageToVitals = (u: Usage): Partial<Vitals> => ({
  pct: u.context?.percent ?? null,
  tokens: u.context?.tokens ?? null,
  window: u.context?.window ?? null,
  costUsd: u.cost?.usd ?? null,
  limits: (u.rateLimits ?? []).map(r => ({ kind: r.kind, pct: r.percentUsed })),
})

/** How many finished turns the sparkline keeps. */
export const MAX_TURNS = 16

/** The turns with `t` added last, the oldest dropped past MAX_TURNS. */
export const pushTurn = (turns: readonly Turn[], t: Turn): Turn[] => [...turns, t].slice(-MAX_TURNS)

/** How full the context is: 0 fine, 1 from 80%, 2 from 90% (time to compact). */
export function contextLevel(pct: number | null): 0 | 1 | 2 {
  if (pct === null) return 0
  return pct >= 90 ? 2 : pct >= 80 ? 1 : 0
}

/** What the turns row shows: each series oldest first (null costs as 0), the latest turn's values and the averages. */
export function turnStats(turns: readonly Turn[]) {
  const known = turns.flatMap(t => (t.cost === null ? [] : [t.cost]))
  const last = turns[turns.length - 1]
  return {
    count: turns.length,
    costs: known.length ? turns.map(t => t.cost ?? 0) : null,
    lastCost: last?.cost ?? null,
    avgCost: known.length ? known.reduce((n, c) => n + c, 0) / known.length : null,
    times: turns.map(t => t.ms),
    lastMs: last?.ms ?? 0,
    avgMs: turns.reduce((n, t) => n + t.ms, 0) / Math.max(1, turns.length),
  }
}

files.hooks/agents/agents.ts:
// Pure logic for Claudashboard: subagent cards and what their tool calls do. No `$` here, so it is testable.
import type { Agent } from '../../types'
import { baseName, toSlash } from '../shared/paths'

/** One line on what a tool call does: `Read middleware.ts`, `Bash npm test`. */
export function describeTool(tool: string, input: Record<string, unknown>): string {
  const str = (k: string) => (typeof input[k] === 'string' ? (input[k] as string) : '')
  const file = str('file_path') || str('notebook_path') || str('path')
  if (file && /^(Read|Edit|Write|MultiEdit|NotebookEdit)$/.test(tool)) return `${tool} ${baseName(toSlash(file))}`
  if (tool === 'Bash') return `$ ${str('command').split('\n')[0]}`
  if (tool === 'Grep' || tool === 'Glob') return `${tool} ${str('pattern')}`
  if (tool === 'WebFetch') return `fetch ${str('url').replace(/^https?:\/\//, '')}`
  if (tool === 'WebSearch') return `search ${str('query')}`
  return tool
}

/** The model a step reports, applied to its agent: context is the step's whole input; output adds up. */
export function stepAgent<A extends { steps: number; ctx: number; out: number; model: string }>(
  a: A,
  model: string,
  usage: { input_tokens?: number; cache_read_input_tokens?: number; cache_creation_input_tokens?: number; output_tokens?: number } | null | undefined,
): A {
  const u = usage ?? {}
  const ctx = (u.input_tokens ?? 0) + (u.cache_read_input_tokens ?? 0) + (u.cache_creation_input_tokens ?? 0)
  return { ...a, model: a.model || model, steps: a.steps + 1, ctx: ctx > 0 ? ctx : a.ctx, out: a.out + (u.output_tokens ?? 0) }
}

/** A stored or partial agent with every field present, so a card from an older version still draws. */
export function normalizeAgent(a: Partial<Agent> & { id: string }): Agent {
  return {
    name: 'agent',
    type: 'agent',
    model: '',
    task: '',
    startedAt: 0,
    steps: 0,
    ctx: 0,
    out: 0,
    tools: 0,
    lastTool: '',
    isBackground: false,
    ...a,
    endedAt: a.endedAt ?? null,
  }
}

/** Finished agents kept in the history, and running ones kept (one whose end never came stays until it is pushed out). */
export const MAX_FINISHED = 20
export const MAX_RUNNING = 24

/** The list to store: the most recent running and finished agents, in their order. */
export function keepAgents(list: Agent[]): Agent[] {
  const oldest = (xs: Agent[], keep: number) => xs.slice(0, Math.max(0, xs.length - keep))
  const dropped = new Set([
    ...oldest(
      list.filter(a => a.endedAt === null),
      MAX_RUNNING,
    ),
    ...oldest(
      list.filter(a => a.endedAt !== null),
      MAX_FINISHED,
    ),
  ])
  return list.filter(a => !dropped.has(a))
}

/** The agent `id` finished at `now`: it moves to the history. */
export function finishAgent(list: Agent[], id: string, now: number): Agent[] {
  return keepAgents(list.map(a => (a.id === id && a.endedAt === null ? { ...a, endedAt: now, lastTool: '' } : a)))
}

